try {

    const g_readJsonFile = global.get("g_readJsonFile");
    const BOOTSTRAP = global.get("BOOTSTRAP");

    const config = g_readJsonFile(BOOTSTRAP.FILES.CONFIG);
    global.set("config", config);

    const alertMgmt = g_readJsonFile(BOOTSTRAP.FILES.ALERT_MGMT);
    global.set("alertMgmt", alertMgmt);

    const alertTemplate = g_readJsonFile(BOOTSTRAP.TEMPLATES.ALERT_TEMPLATE);
    global.set("alertTemplate", alertTemplate);

    const timeZones = g_readJsonFile(BOOTSTRAP.FILES.TIME_ZONES);
    global.set("TIME_ZONES", timeZones);

    // --------------------------------------------------
    // Discover Dashboard 2 pages from flows.json.
    // --------------------------------------------------

    const flowData = g_readJsonFile(BOOTSTRAP.FILES.PAGES_SOURCE_FNAME);

    const pages = flowData
        .filter(n => n.type === "ui-page")
        .map(n => ({
            id: n.id,
            name: n.name || "Unnamed",
            path: n.path || "/"
        }));

    global.set("PAGES", pages);


    // --------------------------------------------------
    // Load and reconcile the page registry.
    // --------------------------------------------------

    let pageRegistry = [];

    try {
        pageRegistry = g_readJsonFile(BOOTSTRAP.FILES.PAGES) || [];
    }
    catch (err) {
        pageRegistry = [];
    }


    // --------------------------------------------------
    // Determine whether the registry contains an
    // incomplete page configuration.
    // --------------------------------------------------

    const registryHasIncomplete = pageRegistry.some(page => {

        const validType =
            typeof page.type === "string" &&
            page.type.trim() !== "" &&
            page.type !== "unconfigured";

        const validOwner =
            typeof page.owner === "string" &&
            page.owner.trim() !== "";

        return validType !== validOwner;
    });


    // --------------------------------------------------
    // Find newly discovered Dashboard pages.
    // --------------------------------------------------

    const newPages = pages.filter(page =>
        !pageRegistry.some(entry => entry.id === page.id)
    );


    // --------------------------------------------------
    // Defer new pages if the current registry contains
    // an incomplete configuration.
    // --------------------------------------------------

    if (newPages.length > 0 && registryHasIncomplete) {

        msg.topic = "pageRegistry/newPagesDeferred";

        msg.payload = {
            count: newPages.length,
            pages: newPages.map(page => page.name)
        };

        global.set("PAGE_REGISTRY", pageRegistry);

        return msg;
    }


    // --------------------------------------------------
    // Reconcile normally.
    // --------------------------------------------------

    pages.forEach(page => {

        const existing = pageRegistry.find(
            entry => entry.id === page.id
        );

        if (existing) {

            existing.name = page.name;
            existing.path = page.path;

        }
        else {

            pageRegistry.push({
                id: page.id,
                name: page.name,
                path: page.path,
                type: "unconfigured",
                owner: null
            });

        }
    });


    global.set("PAGE_REGISTRY", pageRegistry);

}
catch (err) {

    node.error(err);

}

return msg;

