function createDevice(reg) {

    const g_readJsonFile = global.get("g_readJsonFile");
    const BOOTSTRAP = global.get("BOOTSTRAP");

    // Read the architectural device template.
    const device = g_readJsonFile(BOOTSTRAP.TEMPLATES.DEVICE);

    // Populate identity.
    device.identity.appName = reg.appName;
    device.identity.sourceId = reg.sourceId;
    device.identity.deviceId = reg.deviceId;
    device.identity.ipAddress = reg.ipAddress;

    // Populate page identity.
    device.pageId = reg.pageId;

    // Populate heartbeat configuration.
    device.heartbeatMonitoring.interval = reg.heartbeatInterval;
    device.heartbeatMonitoring.timeout = reg.timeout;

    // Initialize registration.
    device.registration.accepted = false;
    device.registration.acceptedDate = null;

    return device;
}

