function g_createPgGlobalVar(device) {

    if (!device || !device.pageId) {
        return {
            success: false,
            created: false,
            reason: "Missing pageId"
        };
    }

    const pageId = device.pageId;

    // Don't overwrite an existing page global.
    if (global.get(pageId) !== undefined) {
        return {
            success: true,
            created: false,
            reason: "Already exists"
        };
    }

//    node.warn("CREATE PAGE GLOBAL DEVICE:");
//    node.warn(device);

    const pageGlobal = {
        identity: {
            uuid: device.identity.deviceId,
            resourceId: device.identity.sourceId,
            fullName: device.identity.appName,
            pageId: device.pageId,
            uiId: device.uiId
        }
    };

    global.set(pageId, pageGlobal);

    return {
        success: true,
        created: true,
        reason: "Created"
    };
}

global.set("g_createPgGlobalVar", g_createPgGlobalVar);

function g_updatePkBkState(shade, state) {

    const status = global.get("status");

    if (!status || !status.pkBk)
        return null;

    if (!(shade in status.pkBk))
        return null ;

    status.pkBk[shade].state = state;

    const onCount =
        (status.pkBk.drvSd.state === "ON" ? 1 : 0) +
        (status.pkBk.wsSd.state === "ON" ? 1 : 0) +
        (status.pkBk.psSd.state === "ON" ? 1 : 0);

    status.pkBkState = onCount >= 2 ? "ON" : "OFF";
    return null;
}

global.set("g_updatePkBkState", g_updatePkBkState);

