    );

    function readTime(parameter) {
        const row = rowsByParameter[parameter];

        if (!row) {
            addError(`Missing configuration parameter: ${parameter}.`);
            return null;
        }

        const valueText = String(row.value ?? "").trim();
        const value = Number(valueText);

        if (valueText === "" || !Number.isFinite(value)) {
            addError(`${parameter} must be a valid time in milliseconds.`);
