// -----------------------------------------------------------------------------
// Validate Entry
//
// Verifies that msg.payload is a canonical LogEvent.
//
// Does not modify the event except to ensure optional members exist.
//
// Output:
//
//     msg.validation = {
//         valid   : true|false,
//         reason  : "...",
//         missing : [ ... ]
//     }
//
// -----------------------------------------------------------------------------

if (typeof msg.payload !== "object" || msg.payload === null) {

    msg.validation = {
        valid: false,
        reason: "Payload is not an object.",
        missing: []
    };

    return msg;
}

const required = [
    "deviceSequence",
    "eventTime",
    "sourceId",
    "file",
    "function",
    "line",
    "recordType",
    "level",
    "eventType",
    "message"
];

const missing = [];

for (const field of required) {
    if (!(field in msg.payload)) {
        missing.push(field);
    }
}

if (missing.length > 0) {

    msg.validation = {
        valid: false,
        reason: "Missing required fields.",
        missing: missing
    };

    return msg;
}

// Ensure optional members exist.
msg.payload.data ??= {};

msg.validation = {
    valid: true,
    reason: "",
    missing: []
};

return msg;

const logEvent = msg.payload;
const SEQUENCE_BLOCK_SIZE = 10000;
const SEQUENCE_RESERVE_MARGIN = 150;

/*-----  CREATE THE EVENT UUID  -----*/

function assignEventUuid(logEvent) {
    logEvent.eventUuid = crypto.randomUUID();
}

/*-----  ASSIGN THE SEQUENCE NUMBER AND TAKE CARE OF ANY NEXT RESERVE ACTIONS NEEDED  -----*/

function assignSequence(logEvent) {

    const opsLogging = global.get("opsLogging");
    const g_saveOpsLogging = global.get("g_saveOpsLogging");

    logEvent.sequence = opsLogging.nextSequence++;

    if (opsLogging.nextSequence >=
        opsLogging.nextReserve - SEQUENCE_RESERVE_MARGIN) {

        opsLogging.nextSequence = opsLogging.nextReserve;
        opsLogging.nextReserve += SEQUENCE_BLOCK_SIZE;

        g_saveOpsLogging();
    }
}

/*-----  ASSIGN THE RECEIVED TIME  -----*/

function assignReceivedTime(logEvent) {
    logEvent.receivedTime = new Date().toISOString();
}

// -----------------------------------------------------------------------------
// Complete LogEvent
//
// Apply Logging Service policy to a canonical LogEvent.
// -----------------------------------------------------------------------------

/*-----  MAIN  -----*/

assignReceivedTime(logEvent);
assignSequence(logEvent);
assignEventUuid(logEvent);

return msg;

