const processStart = Date.now();

// -----------------------------------------------------------------------------
// Process one event
// -----------------------------------------------------------------------------

function processEvent(event) {

    return {
        event: event,
        show: true,
        pending: true
    };
}


// -----------------------------------------------------------------------------
// Process events from the initial file read
// -----------------------------------------------------------------------------

function fromReadFile() {

    const events = flow.get("events") || [];

    const start = Date.now();

    const processedEvents = events.map(event =>
        processEvent(event)
    );

    flow.set("events", processedEvents);
    /*
        node.warn(
            `process data: fromReadFile ${processedEvents.length} events = ` +
            `${Date.now() - start}ms`
        );
    */
}


// -----------------------------------------------------------------------------
// Process events from tail-file
// -----------------------------------------------------------------------------

function fromTailFile() {

    let incomingEvents = msg.payload;

    if (!Array.isArray(incomingEvents)) {
        incomingEvents = [incomingEvents];
    }

    const newEvents = [];

    for (const incomingEvent of incomingEvents) {

        let event = incomingEvent;

        if (typeof event === "string") {

            try {
                event = JSON.parse(event);
            }
            catch (err) {
                node.error(
                    "JSON parse failed. " +
                    "_msgid=" + msg._msgid +
                    ", payloadType=" + typeof msg.payload +
                    ", payloadLength=" +
                    (typeof msg.payload === "string"
                        ? msg.payload.length
                        : "n/a") +
                    ", msg.payload=" + JSON.stringify(msg.payload),
                    msg
                );
                continue;
            }
        }

        if (
            !event ||
            typeof event !== "object" ||
            Array.isArray(event)
        ) {

            node.error(
                "Invalid event received from tail-file.",
                msg
            );

            continue;
        }

        newEvents.push(
            processEvent(event)
        );
    }

    if (newEvents.length === 0) {
        return;
    }

    const events = flow.get("events") || [];
    events.push(...newEvents);
//    flow.set("events", events);
    msg.newEvents = newEvents;
}


// -----------------------------------------------------------------------------
// Select the source
// -----------------------------------------------------------------------------

switch (msg.topic) {

    case "sourced/from/file":
        fromReadFile();
        break;

    case "sourced/from/tail":
        fromTailFile();
        break;

    default:

