// -------------------------------------------------------------

for (const change of changes) {

    const sourceId = change.sourceId;

    if (!sourceId) {
        errors.push("A device is missing its sourceId.");
        continue;
    }

    const device = devices[sourceId];

    if (!device) {
        errors.push(`Unknown device '${sourceId}'.`);
        continue;
    }

    if (typeof change.accepted !== "boolean") {
        errors.push(
            `Invalid accepted value for device '${sourceId}'.`
        );
    }

    if (typeof change.pageName !== "string") {
        errors.push(
            `Invalid pageName for device '${sourceId}'.`
        );
        continue;
    }

    if (typeof change.uiId !== "string") {
        errors.push(
            `Invalid uiId for device '${sourceId}'.`
        );
        continue;
    }

    const pageName = change.pageName.trim();
    const uiId = change.uiId.trim();

    // Empty values mean no page assigned.
    if (pageName === "" || uiId === "")
        continue;

    // Prevent two devices from claiming the same Node-RED page.
    if (seenPages.has(uiId)) {
        errors.push(
            `UI page '${uiId}' is assigned to more than one device.`
        );
    }

    seenPages.add(uiId);
}


