// Helper function to recursively walk the directories
function walkDirectory(currentPath, relativePrefix = "") {
    try {
        const files = fs.readdirSync(currentPath);

        files.forEach(file => {
            // Skip system tracking files and specific metadata directories
            if (['posix', 'right', 'Etc', 'SystemV', 'US', 'Brazil', 'Chile', 'Canada', 'Mexico', 'posixrules', 'localtime', 'zone.tab', 'zone1970.tab'].includes(file)) {
                return;
            }

            const fullPath = path.join(currentPath, file);
            const relName = relativePrefix ? `${relativePrefix}/${file}` : file;
            const stat = fs.statSync(fullPath);

            if (stat.isDirectory()) {
                // Recursively look inside folders (like America, Europe, etc.)
                walkDirectory(fullPath, relName);
            } else if (stat.isFile()) {
                try {
                    const buffer = fs.readFileSync(fullPath);
                    const fileContent = buffer.toString('utf-8');
                    const lines = fileContent.split('\n');

                    // The POSIX string rule sits on the second to last line of a TZif file
                    if (lines.length >= 2) {
                        const posixString = lines[lines.length - 2].trim();

                        // Only add valid, non-empty POSIX strings
                        if (posixString && posixString.length > 2) {
                            timezoneMap[relName] = posixString;
                        }
                    }
                } catch (e) {
                    // Fail silently for single corrupted files
                }
            }
        });
    } catch (err) {
        node.error("Directory reading error: " + err.message);
    }
}

