try {

    const CONFIG_DIR = "/home/admin/.node-red/projects/RVAutomationV2/config";

    const SOURCE_FILE = path.join(CONFIG_DIR, "zones.json");
    const OUTPUT_FILE = path.join(CONFIG_DIR, "time_zones.json");


    // Read the Olson/IANA -> POSIX source data
    const zones = JSON.parse(
        fs.readFileSync(SOURCE_FILE, "utf8")
    );

    const timeZones = {};
    const skipped = [];


    // Convert each Olson/IANA -> POSIX entry into a richer record
    for (const [olsonName, posix] of Object.entries(zones)) {

        // Normal POSIX:
        //   MST7MDT... -> MST
        //
        // Bracketed numeric POSIX:
        //   <-05>5     -> -05
        //   <+01>-1    -> +01
        const match = posix.match(
            /^(?:([A-Za-z]+)|<([^>]+)>)/
        );

        if (!match) {
            skipped.push({
                olsonName,
                posix
            });
            continue;
        }

        const abbreviation = match[1] || match[2];

        timeZones[olsonName] = {
            abbreviation,
            posix
        };
    }

    // Write the generated runtime file
    fs.writeFileSync(
        OUTPUT_FILE,
        JSON.stringify(timeZones, null, 2) + "\n",
        "utf8"
    );


    // Report results
    node.warn(
        `Generated ${OUTPUT_FILE} with ` +
        `${Object.keys(timeZones).length} time zones.`
    );

    if (skipped.length > 0) {
        node.warn(
            `Skipped ${skipped.length} entries without a standard ` +
            `letter-based abbreviation.`
        );
    }


    msg.payload = {
        generated: Object.keys(timeZones).length,
        skipped
    };

    return msg;

}
catch (err) {

    node.error(
        `Time zone generation failed: ${err.message}`,
        msg
    );

    return null;
}

