// -----------------------------------------------------------------------------
// Receive HB
//
// Records receipt of a heartbeat from an accepted device.
//
// Unregistered or unaccepted devices are silently ignored.
// Registration Service owns notification of unknown devices.
//
// Online/offline state is determined exclusively by Timer_tick.
// -----------------------------------------------------------------------------

const sourceId = msg.payload?.sourceId;

if (!sourceId) {
    return null;
}

const devices = global.get("devices") || {};
const device = devices[sourceId];

// -----------------------------------------------------------------------------
// Only accepted devices participate in Heartbeat Service.
// -----------------------------------------------------------------------------

if (!device || !device.registration?.accepted) {
    return null;
}

// -----------------------------------------------------------------------------
// Heartbeat monitoring must be enabled.
// -----------------------------------------------------------------------------

if (!device.heartbeatMonitoring?.enabled) {
    return null;
}

if (!device.heartbeat) {
    return null;
}

// -----------------------------------------------------------------------------
// Record the heartbeat.
//
// Timer_tick owns heartbeatMonitoring.online.
// -----------------------------------------------------------------------------

device.heartbeat.lastHeartbeat = Date.now();

global.set("devices", devices);

return null;

// -----------------------------------------------------------------------------
// Timer Tick
//
// Evaluates heartbeat monitoring for all registered devices.
//
// The devices object is authoritative for device registration and heartbeat
// monitoring state.
//
// The timer runs every few seconds, but produces output only when a heartbeat
// state transition occurs.
//
// -----------------------------------------------------------------------------

const devices = global.get("devices") || {};

const now = Date.now();

let okCount = 0;
let timeoutCount = 0;

const events = [];


// -----------------------------------------------------------------------------
// Evaluate every registered device.
// -----------------------------------------------------------------------------

for (const sourceId in devices) {

    const device = devices[sourceId];

    // -------------------------------------------------------------------------
    // Only accepted devices participate in heartbeat monitoring.
    // -------------------------------------------------------------------------

    if (!device.registration || !device.registration.accepted) {
        continue;
    }

    const monitoring = device.heartbeatMonitoring;
    const heartbeat = device.heartbeat;

    // -------------------------------------------------------------------------
    // Heartbeat monitoring must be enabled.
    // -------------------------------------------------------------------------

    if (!monitoring || !monitoring.enabled) {
        continue;
    }

    // -------------------------------------------------------------------------
    // No heartbeat data available.
    // Treat the device as offline.
    // -------------------------------------------------------------------------

    if (!heartbeat || !heartbeat.lastHeartbeat) {

        timeoutCount++;

        if (!monitoring.initialized) {

            monitoring.initialized = true;
            monitoring.online = false;
            monitoring.missedHeartbeats = 1;
            monitoring.offlineSince = now;

            events.push({
                event: "ALERT_DOWN",
                sourceId: sourceId,
                alertType: "heartbeat",
                state: "broken",
                timestamp: now
            });
        }

        continue;
    }


    // -------------------------------------------------------------------------
    // Determine how long it has been since the last heartbeat.
    // -------------------------------------------------------------------------

    const elapsed = now - heartbeat.lastHeartbeat;


    // -------------------------------------------------------------------------
    // Heartbeat is still within the allowed timeout.
    // -------------------------------------------------------------------------

    if (elapsed <= monitoring.timeout) {

        okCount++;

        // Reset missed-heartbeat count while online.
        monitoring.missedHeartbeats = 0;

        // ---------------------------------------------------------------------
        // If the device was previously offline, this is an OFFLINE -> ONLINE
        // transition.
        //
        // The first heartbeat after startup is NOT a recovery.
        // ---------------------------------------------------------------------

        if (!monitoring.online) {

            const wasInitialized = monitoring.initialized;

            monitoring.initialized = true;
            monitoring.online = true;
            monitoring.offlineSince = 0;

            if (wasInitialized) {

                events.push({
                    event: "ALERT_UP",
                    sourceId: sourceId,
                    alertType: "heartbeat",
                    state: "fixed",
                    timestamp: now,
                    downDuration: 0
                });
            }
        }
        else {

            monitoring.initialized = true;
        }
    }

    // -------------------------------------------------------------------------
    // Heartbeat has exceeded the timeout.
    // -------------------------------------------------------------------------

    else {

        timeoutCount++;

        // ---------------------------------------------------------------------
        // Calculate missed heartbeats from elapsed time rather than counting
        // timer ticks. The timer runs every 5 seconds, but the device heartbeat
        // interval is what defines a missed heartbeat.
        // ---------------------------------------------------------------------

        if (monitoring.interval > 0) {

            monitoring.missedHeartbeats =
                Math.floor(elapsed / monitoring.interval);

        }
        else {

            monitoring.missedHeartbeats = 1;
        }


        // ---------------------------------------------------------------------
        // Only generate an alert on the ONLINE -> OFFLINE transition.
        // ---------------------------------------------------------------------

        if (monitoring.online) {

            monitoring.online = false;
            monitoring.offlineSince = now;

            events.push({
                event: "ALERT_DOWN",
                sourceId: sourceId,
                alertType: "heartbeat",
                state: "broken",
                timestamp: now
            });
        }

        // ---------------------------------------------------------------------
        // If this is the first evaluation and the device has already exceeded
        // its timeout, establish it as offline and generate the initial alert.
        // ---------------------------------------------------------------------

        else if (!monitoring.initialized) {

            monitoring.initialized = true;
            monitoring.online = false;
            monitoring.offlineSince = now;

            events.push({
                event: "ALERT_DOWN",
                sourceId: sourceId,
                alertType: "heartbeat",
                state: "broken",
                timestamp: now
            });
        }
    }
}


// -----------------------------------------------------------------------------
// Persist updated device state.
// -----------------------------------------------------------------------------

global.set("devices", devices);


// -----------------------------------------------------------------------------
// Update node status.
//
// This is informational only and does not generate a message.
// -----------------------------------------------------------------------------

if (timeoutCount === 0) {

    node.status({
        fill: "green",
        shape: "dot",
        text: `${okCount} OK`
    });

}

else {

    node.status({
        fill: "yellow",
        shape: "dot",
        text: `${okCount} OK, ${timeoutCount} timeout`
    });
}


// -----------------------------------------------------------------------------
// Produce output only when a heartbeat state transition occurred.
//
// Ordinary timer ticks produce no message.
// -----------------------------------------------------------------------------

if (events.length === 0) {
    return null;
}


// -----------------------------------------------------------------------------
// Return one message for each state transition.
// -----------------------------------------------------------------------------

return events.map(event => ({
    payload: event
}));

// -----------------------------------------------------------------------------
// TEST: Force Device Offline
//
// Makes a registered device appear to have stopped sending heartbeats.
// The next Timer_tick should detect ONLINE -> OFFLINE.
//
// Set targetSourceId to the device you want to test.
// -----------------------------------------------------------------------------

const devices = global.get("devices") || {};

const targetSourceId = "test_ws_sd";

const device = devices[targetSourceId];

if (!device) {
    node.error(`Test device '${targetSourceId}' not found.`);
    return null;
}

if (!device.heartbeatMonitoring) {
    node.error(`Device '${targetSourceId}' has no heartbeatMonitoring object.`);
    return null;
}

// Make the last heartbeat older than the timeout.
device.heartbeat.lastHeartbeat =
    Date.now() - device.heartbeatMonitoring.timeout - 1000;

// Deliberately leave the device ONLINE so Timer_tick sees the transition.
device.heartbeatMonitoring.online = true;
device.heartbeatMonitoring.missedHeartbeats = 0;

global.set("devices", devices);

node.warn(`Forced '${targetSourceId}' into heartbeat timeout test state.`);

return msg;

