    addError("Configuration data is not an array.");

} else {

    const expectedIds = [1, 2, 3];

    for (const id of expectedIds) {

        const row = data.find(item => item.id === id);

        if (!row) {
            addError(`Missing configuration parameter with id ${id}.`);
        }
    }

    const rowsById = Object.fromEntries(
        data.map(row => [row.id, row])
    );

    // Email Delay
    const delayText = String(rowsById[1]?.value ?? "").trim();
    const delay = Number(delayText);

    if (
        delayText === "" ||
        !Number.isInteger(delay) ||
        delay < 2 ||
        delay > 30
    ) {
        addError(
            "Email Delay must be a whole number from 2 to 30 minutes."
        );
    }

    // Email Recipients
    const recipients = String(rowsById[2]?.value ?? "").trim();

    if (recipients === "") {
        addError(
            "Email Recipients must be specified."
        );
    }

    // Email Reminder
    const reminderText = String(rowsById[3]?.value ?? "").trim();
    const reminder = Number(reminderText);

    if (
        reminderText === "" ||
        !Number.isInteger(reminder) ||
        reminder < 0
    ) {
        addError(
            "Email Reminder must be a whole number of minutes greater than or equal to 0."
        );
    }
}

