        case "partial":
            return "<span style='font-size:22px; color:white; font-weight:bold;'>⚠</span>";

        case "unconfigured":
            return "<span style='font-size:22px; color:white; font-weight:bold;'>○</span>";

        default:
            return "";
    }
}

